From 392015373374d6571e84274ec137950d8dc045b4 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 12:26:57 +0100
Subject: [PATCH] klipper: add an option to not save copied files in the
 history

Files copied or cut in a file manager were always added to the clipboard
history, pushing copied text out, and only image data could be left out.
A new "Files copied or cut in a file manager" option now skips them.

BUG: 349509
---
 klipper/configdialog.cpp |  6 +++++-
 klipper/configdialog.h   |  1 +
 klipper/historymodel.cpp | 17 +++++++++++++++++
 klipper/historymodel.h   |  1 +
 klipper/klipper.kcfg     |  5 +++++
 5 files changed, 29 insertions(+), 1 deletion(-)

diff --git a/klipper/configdialog.cpp b/klipper/configdialog.cpp
index 592dfd8dd8..f37dfc763f 100644
--- a/klipper/configdialog.cpp
+++ b/klipper/configdialog.cpp
@@ -146,7 +146,7 @@ GeneralWidget::GeneralWidget(QWidget *parent)
     connect(imageHint, &QLabel::linkActivated, this, [imageHint]() {
         QToolTip::showText(QCursor::pos(),
                            xi18nc("@info:tooltip",
-                                  "Clipboard will always allow copying image files as filenames and will show their thumbnails. "
+                                  "Image files copied in a file manager are saved as filenames with their thumbnails, subject to the option below. "
                                   " This setting covers cases where images are stored directly as data. "
                                   " Some applications support both cases, but some only accept images as data."
                                   "<nl/>"
@@ -156,6 +156,10 @@ GeneralWidget::GeneralWidget(QWidget *parent)
                                   "Any application that sends both text and image will also ignore it."),
                            imageHint);
     });
+
+    m_saveFilesCb = new QCheckBox(i18nc("@option:check Part of the setting 'Include in history:'", "Files copied or cut in a file manager"), this);
+    m_saveFilesCb->setObjectName(QLatin1String("kcfg_SaveFiles"));
+    layout->addRow(QString(), m_saveFilesCb);
 }

 //////////////////////////
diff --git a/klipper/configdialog.h b/klipper/configdialog.h
index d3d44c97fb..acef398c12 100644
--- a/klipper/configdialog.h
+++ b/klipper/configdialog.h
@@ -36,6 +36,7 @@ private:

     QCheckBox *m_saveSelectionCb;
     QCheckBox *m_saveImagesCb;
+    QCheckBox *m_saveFilesCb;

     QSpinBox *m_historySizeSb;
 };
diff --git a/klipper/historymodel.cpp b/klipper/historymodel.cpp
index 8112dadb5b..30c9c8009f 100644
--- a/klipper/historymodel.cpp
+++ b/klipper/historymodel.cpp
@@ -745,6 +745,18 @@ HistoryItemConstPtr HistoryModel::first() const
     return m_items[0];
 }

+static bool isFileData(const QMimeData *mimeData)
+{
+    if (!mimeData->hasUrls()) {
+        return false;
+    }
+    if (mimeData->hasFormat(QStringLiteral("application/x-kde-cutselection")) || mimeData->hasFormat(QStringLiteral("x-special/gnome-copied-files"))) {
+        return true;
+    }
+    const QList<QUrl> urls = mimeData->urls();
+    return std::ranges::all_of(urls, &QUrl::isLocalFile);
+}
+
 static QString textFromMimeData(const QMimeData *mimeData)
 {
     if (!mimeData->hasUrls()) {
@@ -941,6 +953,7 @@ void HistoryModel::loadSettings()
 {
     setMaxSize(KlipperSettings::maxClipItems());
     m_bSaveImages = KlipperSettings::saveImages();
+    m_bSaveFiles = KlipperSettings::saveFiles();
     m_bNoNullClipboard = KlipperSettings::preventEmptyClipboard();
     m_bSaveSelection = KlipperSettings::saveSelection();
     m_bKeepContents = KlipperSettings::keepClipboardContents();
@@ -1081,6 +1094,10 @@ void HistoryModel::checkClipData(QClipboard::Mode mode, const QMimeData *data)
         return;
     }

+    if (!m_bSaveFiles && isFileData(data)) {
+        return;
+    }
+
     if (insert(data)) [[likely]] {
         qCDebug(KLIPPER_LOG) << "Synchronize?" << m_bSynchronize;
         if (m_bSynchronize) { // applyClipChanges can return nullptr
diff --git a/klipper/historymodel.h b/klipper/historymodel.h
index 15fe0f0f68..a1f4cd3d88 100644
--- a/klipper/historymodel.h
+++ b/klipper/historymodel.h
@@ -171,6 +171,7 @@ private:
     QSqlDatabase m_db;
     qsizetype m_maxSize = 0;
     bool m_bSaveImages = false;
+    bool m_bSaveFiles = true;
     bool m_bNoNullClipboard = true;
     bool m_bSaveSelection = false;
     bool m_bKeepContents = true;
diff --git a/klipper/klipper.kcfg b/klipper/klipper.kcfg
index 088d17f5de..e35df7a5ec 100644
--- a/klipper/klipper.kcfg
+++ b/klipper/klipper.kcfg
@@ -34,6 +34,11 @@
       <default>false</default>
       <whatsthis>Store images in the clipboard history.</whatsthis>
     </entry>
+    <entry name="SaveFiles" type="Bool">
+      <label>Save files</label>
+      <default>true</default>
+      <whatsthis>Store files copied or cut in a file manager in the clipboard history.</whatsthis>
+    </entry>
     <entry name="URLGrabberEnabled" type="Bool">
         <label>When text or a file is copied</label>
 	<tooltip>Show the popup menu as soon as text or file is copied.</tooltip>
-- 
